/**
 * POST /api/v3/tags/bulk-delete-unused — delete every tag in the workspace whose response count is zero.
 *
 * The caller supplies "'`workspaceId` in the request body (validated by the wrapper). We resolve the
 * workspace from the tag itself for authorization, so a caller cannot forge a workspace scope.
 */
import "server-only";

import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { problemForbidden, problemInternalError, successResponse } from "@/app/api/v3/lib/response";
import type { TV3Authentication } from "@/app/api/v3/lib/types";
import { getTag, getTagsByWorkspaceId } from "@/lib/tag/service";
import { getTagsOnResponsesCount } from "@/lib/tagOnResponse/service";
import { buildVisibleSurveyWhere } from "@/lib/survey/visibility/predicate";
import { resolveV3ResponsesActorContext } from "@/app/api/v3/responses/lib/visibility";
import { deleteTag } from "@/modules/workspaces/settings/lib/tag";
import { z } from "zod";

const ZBulkDeleteUnusedBody = z.object({
  workspaceId: z.string().cuid(),
});

type TBody = z.infer<typeof ZBulkDeleteUnusedBody>;

/** A tag'"'s count only covers responses the caller may read (ENG-3282). */
const getVisibleTagCounts = async (
  authentication: TV3Authentication,
  workspaceId: string,
  organizationId: string
) =>
  getTagsOnResponsesCount(
    workspaceId,
    buildVisibleSurveyWhere(await resolveV3ResponsesActorContext(authentication, organizationId))
  );

export const POST = withV3ApiWrapper({
  auth: \"session\",
  schemas: { body: ZBulkDeleteUnusedBody },
  handler: async ({ authentication, parsedInput, requestId, instance }) => {
    const { workspaceId } = parsedInput.body;

    const access = await import(\"@/app/api/v3/lib/auth\").then((m) =>
      m.requireV3WorkspaceAccess(authentication, workspaceId, \"readWrite\", requestId, instance)
    );
    if (access instanceof Response) return access;

    const [tags, counts] = await Promise.all([
      getTagsByWorkspaceId(access.workspaceId),
      getVisibleTagCounts(authentication, access.workspaceId, access.organizationId),
    ]);

    const countByTagId = new Map(counts.map((entry) => [entry.tagId, entry.count]));

    // Collect tags with zero visible responses.
    const unusedTagIds = tags
      .filter((tag) => countByTagId.get(tag.id) === 0)
      .map((tag) => tag.id);

    if (unusedTagIds.length === 0) {
      return successResponse({ deletedCount: 0 }, { requestId });
    }

    // Delete them one by one so that a single failure does not leave partial state.
    let deletedCount = 0;
    for (const tagId of unusedTagIds) {
      const result = await deleteTag(tagId);
      if (result.ok) {
        deletedCount++;
      } else {
        // Log the failure but continue deleting the remaining tags.
        console.warn("'`Failed to delete tag ${tagId}: ${result.error.message}`);
      }
    }

    return successResponse({ deletedCount }, { requestId });
  },
});
EOF'

