/**
 * POST /api/v3/tags/bulk-delete-unused — delete every tag in the workspace whose response count is zero.
 *
 * The caller supplies `workspaceId` in the request body (validated by the wrapper). We resolve the
 * workspace from the tag itself for authorization, so a caller cannot forge a workspace scope.
 */
import "server-only";

import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { problemForbidden, problemInternalError, successResponse } from "@/app/api/v3/lib/response";
import type { TV3Authentication } from "@/app/api/v3/lib/types";
import { getTag, getTagsByWorkspaceId } from "@/lib/tag/service";
import { getTagsOnResponsesCount } from "@/lib/tagOnResponse/service";
import { buildVisibleSurveyWhere } from "@/lib/survey/visibility/predicate";
import { resolveV3ResponsesActorContext } from "@/app/api/v3/responses/lib/visibility";
import { deleteTag } from "@/modules/workspaces/settings/lib/tag";
import { z } from "zod";

const ZBulkDeleteUnusedBody = z.object({
  workspaceId: z.string().cuid(),
});

type TBody = z.infer<typeof ZBulkDeleteUnusedBody>;

/** A tag's count only covers responses the caller may read (ENG-3282). */
const getVisibleTagCounts = async (
  authentication: TV3Authentication,
  workspaceId: string,
  organizationId: string
) =>
  getTagsOnResponsesCount(
    workspaceId,
    buildVisibleSurveyWhere(await resolveV3ResponsesActorContext(authentication, organizationId))
  );

export const POST = withV3ApiWrapper({
  auth: "session",
  schemas: { body: ZBulkDeleteUnusedBody },
  handler: async ({ authentication, parsedInput, requestId, instance }) => {
    const { workspaceId } = parsedInput.body;

    const access = await import("@/app/api/v3/lib/auth").then((m) =>
      m.requireV3WorkspaceAccess(authentication, workspaceId, "readWrite", requestId, instance)
    );
    if (access instanceof Response) return access;

    const [tags, counts] = await Promise.all([
      getTagsByWorkspaceId(access.workspaceId),
      getVisibleTagCounts(authentication, access.workspaceId, access.organizationId),
    ]);

    const countByTagId = new Map(counts.map((entry) => [entry.tagId, entry.count]));

    // Collect tags with zero visible responses.
    const unusedTagIds = tags
      .filter((tag) => countByTagId.get(tag.id) === 0)
      .map((tag) => tag.id);

    if (unusedTagIds.length === 0) {
      return successResponse({ deletedCount: 0 }, { requestId });
    }

    // Delete them one by one so that a single failure does not leave partial state.
    let deletedCount = 0;
    for (const tagId of unusedTagIds) {
      const result = await deleteTag(tagId);
      if (result.ok) {
        deletedCount++;
      } else {
        // Log the failure but continue deleting the remaining tags.
        console.warn(`Failed to delete tag ${tagId}: ${result.error.message}`);
      }
    }

    return successResponse({ deletedCount }, { requestId });
  },
});

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { bulkDeleteUnusedTags } from "../lib/api-client";
import { tagKeys } from "../lib/query";

/**
 * Delete all tags whose response count is zero, then invalidate the tag list.
 * Replaces a `router.refresh()` full-page revalidation.
 */
export const useDeleteUnusedTags = (workspaceId: string) => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: () => bulkDeleteUnusedTags({ workspaceId }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: tagKeys.list(workspaceId) }),
  });
};

import type { TV3Tag } from "@/app/api/v3/tags/serializers";
import { parseV3ApiError } from "@/modules/api/lib/v3-client";

/**
 * Client fetchers for the tags v3 routes. Reads forward the TanStack `signal`; every call throws a parsed
 * `V3ApiError` on a non-2xx response, so the hooks can surface the server's own message.
 */

const BASE_PATH = "/api/v3/tags";

async function request<T>(url: string, init: RequestInit): Promise<T> {
  const response = await fetch(url, { cache: "no-store", ...init });
  if (!response.ok) {
    throw await parseV3ApiError(response);
  }
  return ((await response.json()) as { data: T }).data;
}

export async function getTags(params: { workspaceId: string; signal?: AbortSignal }): Promise<TV3Tag[]> {
  const query = new URLSearchParams({ workspaceId: params.workspaceId });
  return request<TV3Tag[]>(`${BASE_PATH}?${query.toString()}`, {
    method: "GET",
    signal: params.signal,
  });
}

export async function renameTag(params: { tagId: string; name: string }): Promise<TV3Tag> {
  return request<TV3Tag>(`${BASE_PATH}/${params.tagId}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ name: params.name }),
  });
}

export async function deleteTag(params: { tagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}`, { method: "DELETE" });
}

export async function mergeTags(params: { tagId: string; newTagId: string }): Promise<{ id: string }> {
  return request<{ id: string }>(`${BASE_PATH}/${params.tagId}/merge`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ newTagId: params.newTagId }),
  });
}

export async function bulkDeleteUnusedTags(params: { workspaceId: string }): Promise<{ deletedCount: number }> {
  const query = new URLSearchParams({ workspaceId: params.workspaceId });
  return request<{ deletedCount: number }>(`${BASE_PATH}/bulk-delete-unused?${query.toString()}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ workspaceId: params.workspaceId }),
  });
}

"use client";

import { useTranslation } from "react-i18next";
import { SettingsCard } from "@/app/(app)/workspaces/[workspaceId]/settings/components/SettingsCard";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";
import { SettingsTableSkeleton } from "@/modules/ui/components/settings-table";
import { getTagColumns } from "@/modules/workspaces/settings/tags/components/edit-tags-wrapper";

export const TagsLoading = () => {
  const { t } = useTranslation();
  return (
    <PageContentWrapper>
      <PageHeader pageTitle={t("common.tags")} />
      <SettingsCard
        title={t("workspace.tags.manage_tags")}
        description={t("workspace.tags.manage_tags_description")}
        bodyVariant="flush">
        {/*
          Columns come from the table's own factory, so the skeleton cannot drift from the header the way
          the hand-rolled one had.

          `isReadOnly: false` is a genuine limitation rather than a choice: a route `loading.tsx` receives
          no props and has no auth context, so it cannot know whether the actions column will be there. It
          renders the editor's three columns, which is the common case. The widths do not rely on summing
          to exactly 100% — `table-auto` rescales the rest when a column is absent.

          `workspaceId` and `tags` are never read: the skeleton renders headers and placeholder bars, and
          never calls `cell`.
        */}
        <SettingsTableSkeleton columns={getTagColumns({ t, workspaceId: "", tags: [], isReadOnly: false })} />
      </SettingsCard>
    </PageContentWrapper>
  );
};

